#define _XOPEN_SOURCE 700

#include <dirent.h>
#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#include "inventory.h"
#include "path.h"
#include "platform.h"
#include "session.h"
#include "util.h"

static int missing(int err)
{
	return err == ENOENT || err == ENOTDIR;
}

/*
 * Whether path lies below a mount parent (platform_mount_parents) with no
 * volume mounted on the way: every existing directory between the parent
 * and path is on the parent's own device. A symlink there counts as a
 * mount, so "/Volumes/Macintosh HD" (a link to "/") is never unavailable.
 */
static int volume_missing(const char *path, const char *parent)
{
	struct stat top, st;
	char *prefix;
	const char *p;
	size_t n;
	int gone = 1;

	n = strlen(parent);
	if (!path_has_prefix(path, parent) || path[n] != '/' ||
	    stat(parent, &top) != 0)
		return 0;
	prefix = xmalloc(strlen(path) + 1);
	for (p = path + n + 1; gone; p++) {
		p = strchr(p, '/');
		if (p == NULL)
			p = path + strlen(path);
		memcpy(prefix, path, (size_t)(p - path));
		prefix[p - path] = '\0';
		if (lstat(prefix, &st) != 0)
			break;
		if (S_ISLNK(st.st_mode) || st.st_dev != top.st_dev)
			gone = 0;
		if (*p == '\0')
			break;
	}
	free(prefix);
	return gone;
}

/*
 * The state of a project path. Orphaned means nothing but ENOENT (or
 * ENOTDIR) from the path up to its closest existing ancestor. Any other
 * error, a dangling symlink on the way (its target may be on a volume that
 * is not mounted) or a missing volume makes it unavailable: a session
 * directory wrongly called orphaned could be removed.
 */
enum dir_state path_state(const char *path, const char *const *mount_parents)
{
	struct stat st;
	char *cur, *up;
	enum dir_state state = STATE_ORPHAN;
	size_t i;

	if (path == NULL)
		return STATE_UNKNOWN;
	if (stat(path, &st) == 0)
		return STATE_ACTIVE;
	cur = xstrdup(path);
	for (;;) {
		if (stat(cur, &st) == 0)
			break;
		if (!missing(errno) ||
		    (lstat(cur, &st) == 0 && S_ISLNK(st.st_mode))) {
			state = STATE_UNAVAILABLE;
			break;
		}
		up = path_dir(cur);
		if (strcmp(up, cur) == 0) {
			free(up);
			break;
		}
		free(cur);
		cur = up;
	}
	free(cur);
	for (i = 0; state == STATE_ORPHAN && mount_parents[i] != NULL; i++)
		if (volume_missing(path, mount_parents[i]))
			state = STATE_UNAVAILABLE;
	return state;
}

/* Fixed names for --json; people see the translated words. */
const char *state_name(enum dir_state state)
{
	switch (state) {
	case STATE_ACTIVE:
		return "active";
	case STATE_ORPHAN:
		return "orphan";
	case STATE_UNAVAILABLE:
		return "unavailable";
	case STATE_UNKNOWN:
		break;
	}
	return "unknown";
}

/* Adds up the regular files below dir, never following symlinks. */
void inventory_walk(const char *dir, unsigned long long *size,
    time_t *newest, int *any)
{
	struct dirent *e;
	struct stat st;
	char *path;
	DIR *d;

	d = opendir(dir);
	if (d == NULL)
		return;
	while ((e = readdir(d)) != NULL) {
		if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0)
			continue;
		path = xjoin(dir, e->d_name);
		if (lstat(path, &st) == 0) {
			if (S_ISDIR(st.st_mode)) {
				inventory_walk(path, size, newest, any);
			} else if (S_ISREG(st.st_mode)) {
				*size += (unsigned long long)st.st_size;
				if (!*any || st.st_mtime > *newest)
					*newest = st.st_mtime;
				*any = 1;
			}
		}
		free(path);
	}
	closedir(d);
}

/* Everything csm -l shows about the session directory at path. */
void inventory_read_dir(const char *path, struct session_dir_info *info)
{
	struct stat st;
	char **files;
	int any = 0;

	memset(info, 0, sizeof *info);
	info->path = xstrdup(path);
	info->name = path_base(path);
	info->project = session_dir_cwd(path);
	info->state = path_state(info->project, platform_mount_parents);
	files = session_files(path, &info->sessions);
	session_files_free(files, info->sessions);
	inventory_walk(path, &info->size, &info->modified, &any);
	if (!any && lstat(path, &st) == 0)
		info->modified = st.st_mtime;
}

/* By project path, byte by byte; directories without one go last. */
static int compare_dirs(const void *a, const void *b)
{
	const struct session_dir_info *x = a, *y = b;

	if ((x->project == NULL) != (y->project == NULL))
		return x->project == NULL ? 1 : -1;
	if (x->project != NULL && strcmp(x->project, y->project) != 0)
		return strcmp(x->project, y->project);
	return strcmp(x->name, y->name);
}

/*
 * All session directories in projects_dir (real directories, never
 * symlinks). A missing projects_dir is an empty list; -1 with errno when
 * it cannot be read.
 */
int inventory_scan(const char *projects_dir, struct inventory *inv)
{
	struct dirent *e;
	struct stat st;
	char *path;
	size_t cap = 0;
	DIR *d;

	inv->dirs = NULL;
	inv->count = 0;
	d = opendir(projects_dir);
	if (d == NULL)
		return errno == ENOENT ? 0 : -1;
	while ((e = readdir(d)) != NULL) {
		if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0)
			continue;
		path = xjoin(projects_dir, e->d_name);
		if (lstat(path, &st) == 0 && S_ISDIR(st.st_mode)) {
			if (inv->count == cap) {
				cap = cap ? cap * 2 : 16;
				inv->dirs = xrealloc(inv->dirs,
				    cap * sizeof *inv->dirs);
			}
			inventory_read_dir(path, &inv->dirs[inv->count++]);
		}
		free(path);
	}
	closedir(d);
	if (inv->count > 0)
		qsort(inv->dirs, inv->count, sizeof *inv->dirs, compare_dirs);
	return 0;
}

static int dir_matches(const struct session_dir_info *info,
    const char *variant)
{
	char *encoded;
	int match;

	if (variant == NULL)
		return 0;
	if (info->project != NULL)
		return strcmp(info->project, variant) == 0;
	encoded = path_encode(variant);
	match = strcmp(encoded, info->name) == 0;
	free(encoded);
	return match;
}

/*
 * The session directories csm -s ARG means, as indexes into found (room
 * for inv->count). A bare name of a session directory is that directory;
 * anything else is a project path, in both variants (3.1). A directory
 * without a project path matches by name, as in 4.3.
 */
size_t inventory_match(const struct inventory *inv, const char *arg,
    size_t *found)
{
	char *logical, *physical;
	size_t i, n = 0;

	if (strchr(arg, '/') == NULL)
		for (i = 0; i < inv->count; i++)
			if (strcmp(inv->dirs[i].name, arg) == 0) {
				found[0] = i;
				return 1;
			}
	logical = path_logical(arg);
	physical = path_physical(arg);
	for (i = 0; i < inv->count; i++)
		if (dir_matches(&inv->dirs[i], logical) ||
		    dir_matches(&inv->dirs[i], physical))
			found[n++] = i;
	free(logical);
	free(physical);
	return n;
}

void inventory_free(struct inventory *inv)
{
	size_t i;

	for (i = 0; i < inv->count; i++) {
		free(inv->dirs[i].name);
		free(inv->dirs[i].path);
		free(inv->dirs[i].project);
	}
	free(inv->dirs);
	inv->dirs = NULL;
	inv->count = 0;
}
